// Category A — behavior is borrowed from react-aria-components; look is owned here.
import { ColorSwatch as AriaColorSwatch } from "react-aria-components";
import type { ColorSwatchProps as AriaColorSwatchProps } from "react-aria-components";
import type { Ref } from "react";
import "./ColorSwatch.css";

type ColorSwatchSize = "small" | "medium" | "large";

export interface ColorSwatchProps extends Omit<AriaColorSwatchProps, "className"> {
  /**
   * Visual size.
   *
   * @default "medium"
   */
  size?: ColorSwatchSize;
  /** Additional class. sd-color-swatch is always preserved. */
  className?: string;
  /** Passed to the underlying swatch DOM node. */
  ref?: Ref<HTMLDivElement>;
}

export function ColorSwatch({
  size = "medium",
  className,
  ref,
  ...props
}: ColorSwatchProps) {
  return (
    <AriaColorSwatch
      {...props}
      ref={ref}
      data-size={size}
      className={className ? `sd-color-swatch ${className}` : "sd-color-swatch"}
    />
  );
}

/* react-aria sets the swatch's background-color to the current color; we own size,
   border and radius. (Solid fill — no alpha checkerboard: it can't sit behind a
   react-aria-controlled background-color on a single element without extra DOM.) */
.sd-color-swatch {
  width: var(--sd-color-swatch-size-medium);
  height: var(--sd-color-swatch-size-medium);
  border: var(--sd-color-swatch-border-width) solid var(--sd-color-swatch-border);
  border-radius: var(--sd-color-swatch-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  box-sizing: border-box;
  forced-color-adjust: none;
  /* A swatch's box IS its content, in both axes, so it must never pay for a neighbour's width.
     Inert outside a flex row; inside one, `flex-shrink` defaults to 1 and the declared width above
     stops being a width: a `small` swatch beside a ColorField in a `Stack direction="row"` renders
     7x16, a sliver unrecognisable as a swatch. Same family
     as block-contract.md §4's stretched chip: a box that is content in both axes is always a defect
     when a layout resizes it. Fixed here rather than at the call site because any consumer that
     puts one in a tight row hits it. */
  flex: none;
}

.sd-color-swatch[data-size="small"] {
  width: var(--sd-color-swatch-size-small);
  height: var(--sd-color-swatch-size-small);
}
.sd-color-swatch[data-size="medium"] {
  width: var(--sd-color-swatch-size-medium);
  height: var(--sd-color-swatch-size-medium);
}
.sd-color-swatch[data-size="large"] {
  width: var(--sd-color-swatch-size-large);
  height: var(--sd-color-swatch-size-large);
}
